-- OWNER-approved existing-photo snapshot. Future discovery never approves new files.
CREATE TABLE headshot_public_checks (
 wix_item_id TEXT PRIMARY KEY REFERENCES headshot_leaders(wix_item_id),
 check_state TEXT NOT NULL CHECK(check_state IN ('AVAILABLE','UNAVAILABLE','CHECKING')),
 checked_at TEXT,
 lease_until TEXT
);
CREATE TABLE headshot_public_photos (
 wix_item_id TEXT NOT NULL REFERENCES headshot_leaders(wix_item_id),
 file_id TEXT NOT NULL,
 approval_state TEXT NOT NULL CHECK(approval_state IN ('APPROVED','REVOKED')),
 approved_at TEXT NOT NULL,
 PRIMARY KEY(wix_item_id,file_id)
);
CREATE TABLE headshot_public_media (
 file_id TEXT PRIMARY KEY,
 source_version TEXT,
 media_state TEXT NOT NULL DEFAULT 'PENDING' CHECK(media_state IN ('PENDING','PROCESSING','READY','FAILED')),
 wix_file_url TEXT,
 content_hash TEXT,
 mime_type TEXT,
 byte_length INTEGER,
 request_id TEXT,
 failure_count INTEGER NOT NULL DEFAULT 0,
 next_retry_at TEXT,
 updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);

